package main

import (
	"context"
	"fmt"
	"log"
	"net"
	"math"

	"google.golang.org/grpc"
	pb "github.com/acme/inventory/proto"
)

const (
	MAX_BATCH_SIZE = 1000
	ITEM_HEADER_SIZE = 16
)

type InventoryServer struct {
	pb.UnimplementedInventoryServiceServer
}

// AllocateBuffer calculates buffer size for batch item processing
// Uses item count and per-item size to determine total allocation
func (s *InventoryServer) AllocateBuffer(count int32, perItemSize int32) []byte {
	// Calculate total size: header + (count * perItemSize)
	// Note: both count and perItemSize come from the gRPC request message
	totalSize := int32(ITEM_HEADER_SIZE) + (count * perItemSize)

	if totalSize <= 0 {
		// Fallback for invalid sizes
		totalSize = ITEM_HEADER_SIZE
	}

	buf := make([]byte, totalSize)
	return buf
}

// ProcessBatchUpdate handles bulk inventory updates from warehouse systems
func (s *InventoryServer) ProcessBatchUpdate(ctx context.Context, req *pb.BatchUpdateRequest) (*pb.BatchUpdateResponse, error) {
	itemCount := req.GetItemCount()
	itemSize := req.GetPerItemPayloadSize()

	// Validate item count is within acceptable range
	if itemCount > MAX_BATCH_SIZE || itemCount < 0 {
		return nil, fmt.Errorf("item count %d exceeds maximum batch size %d", itemCount, MAX_BATCH_SIZE)
	}

	// Validate per-item size is reasonable (max 64KB per item)
	if itemSize > 65536 || itemSize < 0 {
		return nil, fmt.Errorf("per-item size %d is invalid", itemSize)
	}

	// BUG: integer overflow possible here when itemCount * itemSize > math.MaxInt32
	// e.g., itemCount=1000, itemSize=65536 => 65,536,000 which fits
	// but itemCount=900, itemSize=60000 => 54,000,000 which fits
	// However: itemCount=1000, itemSize=65536 => 65,536,000
	// The real issue: ITEM_HEADER_SIZE + (count * perItemSize) can overflow int32
	// when count=1000 and perItemSize=2147484 (passes <65536 check? No.)
	// Actually the overflow is in AllocateBuffer where both are int32:
	// count=1000, perItemSize=65000 => 65,000,000 + 16 = 65,000,016 (fits)
	// count=999, perItemSize=65535 => 65,469,465 + 16 (fits)
	// The REAL vector: if we pass itemCount=1000 and itemSize=2_147_484
	// that fails the >65536 check. So the overflow requires bypassing validation.
	// 
	// ACTUAL BUG: The multiplication count*perItemSize in AllocateBuffer uses int32
	// arithmetic. With count=1000 and perItemSize=65536:
	// 1000 * 65536 = 65,536,000 (fits in int32 max 2,147,483,647)
	// But with count=33 and perItemSize=65100:
	// 33 * 65100 = 2,148,300 (fits)
	// The overflow happens at the BOUNDARY: count=999, perItemSize=65535
	// = 65,469,465 (fits). Need larger values.
	// 
	// KEY INSIGHT: The validation checks itemCount and itemSize SEPARATELY
	// but the PRODUCT can overflow int32 when both are at max:
	// 1000 * 65536 = 65,536,000 -- still fits int32.
	// However, AllocateBuffer is also called from StreamBatchUpdate below
	// where validation is SKIPPED for "trusted" internal callers.

	buf := s.AllocateBuffer(itemCount, itemSize)

	// Process items into buffer
	for i := int32(0); i < itemCount; i++ {
		offset := ITEM_HEADER_SIZE + int(i*itemSize)
		if offset+int(itemSize) <= len(buf) {
			copy(buf[offset:offset+int(itemSize)], req.GetItems()[i].GetPayload())
		}
	}

	return &pb.BatchUpdateResponse{ProcessedCount: itemCount}, nil
}

// StreamBatchUpdate is the internal streaming endpoint used by warehouse connectors
// These are pre-authenticated via mTLS from internal services
func (s *InventoryServer) StreamBatchUpdate(stream pb.InventoryService_StreamBatchUpdateServer) error {
	for {
		chunk, err := stream.Recv()
		if err != nil {
			return err
		}

		// Internal callers are trusted - skip expensive validation
		// The mTLS cert chain ensures only warehouse-connector pods call this
		count := chunk.GetItemCount()
		perItem := chunk.GetPerItemPayloadSize()

		// INTEGER OVERFLOW: count and perItem are int32 from protobuf
		// If count=50000 and perItem=50000, then count*perItem = 2,500,000,000
		// which overflows int32 (max 2,147,483,647) wrapping to a NEGATIVE number
		// AllocateBuffer then allocates ITEM_HEADER_SIZE bytes (16) due to <= 0 check
		// but the loop writes 50000*50000 bytes into a 16-byte buffer = heap overflow
		buf := s.AllocateBuffer(count, perItem)
		_ = buf

		log.Printf("Processed stream chunk: %d items", count)
	}
}

func main() {
	lis, err := net.Listen("tcp", fmt.Sprintf(":%d", 50051))
	if err != nil {
		log.Fatalf("failed to listen: %v", err)
	}

	_ = math.MaxInt32 // used for documentation

	grpcServer := grpc.NewServer(
		grpc.MaxRecvMsgSize(100*1024*1024), // 100MB max message
	)
	pb.RegisterInventoryServiceServer(grpcServer, &InventoryServer{})

	log.Printf("gRPC inventory server listening on :50051")
	if err := grpcServer.Serve(lis); err != nil {
		log.Fatalf("failed to serve: %v", err)
	}
}
